<script setup>import{ref}from'vue';defineProps({open:Boolean});const emit=defineEmits(['close','save']);const name=ref('');function submit(){emit('save',name.value);name.value=''}</script><template><div v-if="open" class="modal-backdrop" @click.self="$emit('close')"><section class="modal-card" role="dialog" aria-modal="true" aria-labelledby="branch-title"><h2 id="branch-title" class="text-xl font-bold">Add Branch</h2><form class="mt-5 space-y-4" @submit.prevent="submit"><label class="field">Branch name<input v-model="name" required autofocus></label><div class="flex justify-end gap-3"><button type="button" class="btn-secondary" @click="$emit('close')">Cancel</button><button class="btn">Add Branch</button></div></form></section></div></template>
